WITH recent_suppliers AS (SELECT *, CASE WHEN rating >= 4.0 THEN 'High' WHEN rating >= 1.5 THEN 'Medium' ELSE 'Low' END AS rating_level FROM suppliers WHERE city IN ('Bangkok', 'Chiang Mai') AND UPPER(supplier_name) LIKE '%URO%'), agg AS (SELECT country, city, SUM(CASE WHEN city = 'London' THEN rating ELSE 0 END) AS london_rating, SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END) AS us_count FROM recent_suppliers GROUP BY country, city) SELECT country, city, london_rating, us_count FROM agg WHERE london_rating >= 57
